  /**
   * @method
   * @name kraken#createOrderWs
   * @description create a trade order
   * @see
   * https://docs.kraken.com/exchange/api-reference/spot-websocket-v2/add_order
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  createOrderWs(ccxt::any symbol, ccxt::any type, ccxt::any side, ccxt::any amount,
                ccxt::any price = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 ccxt::any token = awaitValue(this->authenticate());
                 ccxt::any market = this->market(symbol);
                 ccxt::any url = ::getValue(
                     ::getValue(::getValue(this->urls, std::string("api")),
                                std::string("ws")),
                     std::string("privateV2"));
                 ccxt::any requestId = this->requestId();
                 ccxt::any messageHash = this->numberToString(requestId);
                 ccxt::any request = ccxt::dict{
                     {std::string("method"), std::string("add_order")},
                     {std::string("params"),
                      ccxt::dict{
                          {std::string("order_type"), type},
                          {std::string("side"), side},
                          {std::string("order_qty"),
                           this->parseToNumeric(
                               this->amountToPrecision(symbol, amount))},
                          {std::string("symbol"),
                           ::getValue(market, std::string("symbol"))},
                          {std::string("token"), token},
                      }},
                     {std::string("req_id"), requestId},
                 };
                 ccxt::any requestparamsVariable =
                     this->orderRequestWs(std::string("createOrderWs"), symbol,
                                          type, request, amount, price, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 return awaitValue(this->watch(url, messageHash,
                                               this->extend(request, params),
                                               messageHash));
               })
        .share();
  }

  virtual void handleCreateEditOrder(ccxt::any client, ccxt::any message) {
    //
    //  createOrder
    //     {
    //         "method": "add_order",
    //         "req_id": 1,
    //         "result": {
    //             "order_id": "OXM2QD-EALR2-YBAVEU"
    //         },
    //         "success": true,
    //         "time_in": "2025-05-13T10:12:13.876173Z",
    //         "time_out": "2025-05-13T10:12:13.890137Z"
    //     }
    //
    //  editOrder
    //     {
    //         "method": "amend_order",
    //         "req_id": 1,
    //         "result": {
    //             "amend_id": "TYDLSQ-OYNYU-3MNRER",
    //             "order_id": "OGL7HR-SWFO4-NRQTHO"
    //         },
    //         "success": true,
    //         "time_in": "2025-05-14T13:54:10.840342Z",
    //         "time_out": "2025-05-14T13:54:10.855046Z"
    //     }
    //
    ccxt::any result =
        this->safeDict(message, std::string("result"), ccxt::dict{});
    ccxt::any order = this->parseOrder(result);
    ccxt::any messageHash =
        this->safeString2(message, std::string("reqid"), std::string("req_id"));
    this->resolve(order, messageHash);
  }

  /**
   * @method
   * @name kraken#editOrderWs
   * @description edit a trade order
   * @see
   * https://docs.kraken.com/exchange/api-reference/spot-websocket-v2/amend_order
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of the currency you want to trade in units
   * of the base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  editOrderWs(ccxt::any id, ccxt::any symbol, ccxt::any type, ccxt::any side,
              ccxt::any amount = ccxt::any{}, ccxt::any price = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 ccxt::any token = awaitValue(this->authenticate());
                 ccxt::any url = ::getValue(
                     ::getValue(::getValue(this->urls, std::string("api")),
                                std::string("ws")),
                     std::string("privateV2"));
                 ccxt::any requestId = this->requestId();
                 ccxt::any messageHash = this->numberToString(requestId);
                 ccxt::any request = ccxt::dict{
                     {std::string("method"), std::string("amend_order")},
                     {std::string("params"),
                      ccxt::dict{
                          {std::string("order_id"), id},
                          {std::string("order_qty"),
                           this->parseToNumeric(
                               this->amountToPrecision(symbol, amount))},
                          {std::string("token"), token},
                      }},
                     {std::string("req_id"), requestId},
                 };
                 ccxt::any requestparamsVariable =
                     this->orderRequestWs(std::string("editOrderWs"), symbol,
                                          type, request, amount, price, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 return awaitValue(this->watch(url, messageHash,
                                               this->extend(request, params),
                                               messageHash));
               })
        .share();
  }

